import { mkdirSync, writeFileSync, readFileSync, chmodSync } from 'node:fs';
import { spawnSync } from 'node:child_process';
import { createHash } from 'node:crypto';
import assert from 'node:assert/strict';
const out='/tmp/qs-lex-runtime-st2tih6o/fresh-run', fixture=out+'/unlazy-project', approvals=out+'/unlazy-approvals';
for (const p of [fixture,approvals])mkdirSync(p,{recursive:true});chmodSync(approvals,0o700);
const engine='/github/skills/skills/engineering/qs-unlazy/modules/unlazy/scripts/gate-check.mjs';
const hash=x=>createHash('sha256').update(x).digest('hex'); const results=[];
const env={...process.env,UNLAZY_APPROVAL_DIR:approvals};
function run(label,args,expected){
 const argv=[engine,...args,'--root',fixture,'GATES.md'];
 const r=spawnSync(process.execPath,argv,{cwd:fixture,env,encoding:'utf8',timeout:20000});
 const result={label,executable:process.execPath,args:argv,expected,status:r.status,signal:r.signal,error:r.error?.message,stdout:r.stdout,stderr:r.stderr};
 results.push(result);writeFileSync(out+'/unlazy-results.json',JSON.stringify(results,null,2)+'\n');
 writeFileSync(out+'/unlazy-'+label+'-ledger.md',readFileSync(fixture+'/GATES.md'));
 assert.equal(r.error,undefined,label+' subprocess started');assert.equal(r.status,expected,label);return r;
}
const oracle=`import fs from 'node:fs';import assert from 'node:assert/strict';\nconst rows=JSON.parse(fs.readFileSync('rows.json'));\nassert.equal(rows.reduce((sum,row)=>sum+row.quantity*row.price,0),83);\nassert.equal(rows.length,3);console.log('CALCULATED_TOTAL_83');\n`;
writeFileSync(fixture+'/oracle.mjs',oracle);
writeFileSync(fixture+'/rows.json',JSON.stringify([{quantity:2,price:11},{quantity:3,price:7},{quantity:5,price:8}])+'\n');
writeFileSync(fixture+'/GATES.md','# LEX-12 fresh isolated evidence\n- [ ] G1: Three source rows calculate total 83\n  CHECK: node oracle.mjs\n  EXPECT: CALCULATED_TOTAL_83\n  EVIDENCE: pending\n');
run('unapproved', ['--shell','/bin/sh'],1);
assert.equal(readFileSync(fixture+'/GATES.md','utf8').includes('automatic-evidence='),false);
run('approved-pass',['--approve','--shell','/bin/sh'],0);
assert.match(readFileSync(fixture+'/GATES.md','utf8'),/automatic-evidence=v1/);
const valid=readFileSync(fixture+'/GATES.md','utf8');
writeFileSync(fixture+'/GATES.md',valid.replace('EXPECT: CALCULATED_TOTAL_83','EXPECT: CALCULATED_TOTAL_84'));
run('changed-definition-stale',['--status'],1);
writeFileSync(fixture+'/GATES.md',valid);
run('restored-definition',['--status'],0);
writeFileSync(fixture+'/rows.json',JSON.stringify([{quantity:2,price:11},{quantity:3,price:7},{quantity:5,price:9}])+'\n');
run('artifact-change-status-limit',['--status'],0);
run('parent-reverify-detects-bad-artifact',['--reverify','--shell','/bin/sh'],1);
assert.match(readFileSync(fixture+'/GATES.md','utf8'),/- \[ \] G1/);
writeFileSync(fixture+'/rows.json',JSON.stringify([{quantity:2,price:11},{quantity:3,price:7},{quantity:5,price:8}])+'\n');
run('parent-reverify-restored',['--reverify','--shell','/bin/sh'],0);
writeFileSync(fixture+'/GATES.md','# LEX-12 abandonment negative control\n- [ ] G1: Required outcome unavailable\n  EVIDENCE: pending\nABANDON: G1 isolated negative control\n');
const abandoned=run('abandonment',['--status'],1);assert.match(abandoned.stdout,/HANDOFF REQUIRED/);assert.doesNotMatch(abandoned.stdout,/ALL MET/);
writeFileSync(out+'/unlazy-summary.json',JSON.stringify({scope:'Fresh actual local Node 24 Linux engine execution only; no hooks or installed host acceptance.',engine,engineSHA256:hash(readFileSync(engine)),oracleSHA256:hash(oracle),commands:results.length,expectedExitCodes:results.map(x=>x.status),allExpected:true,network:'No network APIs in fixture or gate commands. No package/model acquisition.'},null,2)+'\n');
console.log('UNLAZY_FRESH_LOCAL_PROBES_PASS '+results.length);
